def baseline_offers(apps, schema_editor):
    Offer = apps.get_model("features", "HousingOffer")
    for offer in Offer.objects.select_related("request").iterator():
        parent = offer.request
        if offer.request_revision == parent.revision:
            offer.reviewed_request_snapshot = {
                "title": parent.title,
                "note": parent.note,
                "criteria": parent.criteria,
            }
        elif offer.status in {"sent", "viewed", "shortlisted", "selected_to_proceed"}:
            offer.reviewed_content_revision = 0
            offer.review_state = "incompatible"
            offer.review_reasons = ["Review the changed source housing response."]
        offer.save(
            update_fields=[
                "reviewed_request_snapshot",
                "reviewed_content_revision",
                "review_state",
                "review_reasons",
            ]
        )


